message.content:
{
  "action": "interview_Alma",
  "words": "I'm taking this afternoon. I need to get the last reel out of the Rialto before the line closes. I'm going to handle the recording myself. Don't wait for me at the ballroom; just make sure the crew is ready to roll when I get back with the tape.",
  "intention": "To record Alma's voice for her daughter in Pittsburgh and secure the final reel of the Rialto before the regional line leaves town.",
  "detail": "I pick up the camera bag and the spare microphone from the coffee table, leave the TV crew in the lobby, and walk out the hotel doors toward the Rialto."
}
